public function listeImprimer($etat=null, $id=null, $nature=null,$agent=null){
    $em = $this->getEntityManager();
    $role=$agent->getRoles();
    if(in_array('ROLE_RESPO_SRHMG',$role)){
      $q="";
    }else{
      $q=" and r.matAgent = :agent";
    }
    $agent=$agent->getAgent();
    $dql="SELECT r as regularisation, f.libFonc as oldFonction, fN.libFonc as newFonction, e.libEmpl as oldEmploi, eN.libEmpl as newEmploi, change as changement
       FROM AgentBundle:Regularisation r 
          LEFT JOIN AgentBundle:Emploi e WITH r.old = e.id and r.nature=1 
          LEFT JOIN AgentBundle:Fonction f WITH r.old = f.id and r.nature=2 
          LEFT JOIN AgentBundle:Emploi eN WITH r.new = eN.id and r.nature=1 
          LEFT JOIN AgentBundle:Fonction fN WITH r.new = fN.id and r.nature=2 
          LEFT JOIN AgentBundle:Agent agt WITH r.agent = agt.id
                LEFT JOIN AgentBundle:Changement change WITH (agt.id = change.matAgent and change.id in (Select max(c.id) 
                  From AgentBundle:Changement c Where c.matAgent = agt.id)) 
            ";// 
                  /*(Select max(Changement.id) 
                  From AgentBundle:Changement Where Changement.matAgent = agt.id)*/
  if ($id != null){
                    $dql= $dql." WHERE r.id = :id and r.nature = :nature".$q;
                   // $query->setParameter('id', $id);
                  }else{
                    $dql= $dql." WHERE r.etatImprimer = :etat  and r.nature = :nature".$q;
                   // $query->setParameter('etat', $etat);
                     
                  }

$query = $em->createQuery($dql);
if ($id != null){
                    //$dql= $dql." WHERE r.id = :id";
                   $query->setParameter('id', $id);
                   
                  }else{
                    //$dql= $dql." WHERE r.etatImprimer = :etat";
                   $query->setParameter('etat', $etat);
                     
                  }
$query->setParameter('nature', $nature);


if (!empty($q)){
  $query->setParameter('agent', $agent);
}
/*$retour=$query->getResult(); 
return $retour;*/
///////////Fin///////////
$w = array_chunk($query->getResult(),2,true);
$x=[];
foreach($w as  $key =>$vals){
  $val=[];
  foreach ($vals as $value) {
    if($value==null){ 
      $value=[];
    }
    $val = array_merge($val, $value);
  }
  $x[]=$val;

}


return $x;
}
